new file mode 100644
index 000000000..ff85dcf31
--- /dev/null
+++ b/api/src/notifications/inApp/identity.ts
@@ -0,0 +1,39 @@
+import type { FastifyRequest } from 'fastify';
+
+type IdentitySource = {
+  auth?: { email?: unknown; username?: unknown } | null;
+  session?: { email?: unknown; username?: unknown } | null;
+};
+
+/**
+ * Shared identity → notification mailbox resolution for Fastify requests and
+ * oRPC contexts.
+ *
+ * `notifications.user_email` is what every writer keys on, so the Keycloak
+ * `email` claim wins; the Rust session falls back to `username`, which on this
+ * platform is the email address. Non-email usernames (service accounts) yield
+ * `undefined` so they never read another user's mailbox.
+ *
+ * @example
+ * ```ts
+ * emailFromIdentity({ auth: { username: 'agent@spotlessbinco.com' } });
+ * // 'agent@spotlessbinco.com'
+ * ```
+ */
+export function emailFromIdentity(source: IdentitySource): string | undefined {
+  const candidate = source.auth?.email ?? source.auth?.username
+    ?? source.session?.email ?? source.session?.username;
+  return typeof candidate === 'string' && candidate.includes('@') ? candidate.toLowerCase() : undefined;
+}
+
+/**
+ * Resolves the notification mailbox of an authenticated Fastify request.
+ *
+ * @example
+ * ```ts
+ * const email = callerEmail(request); // 'riley@spotlessbinco.com'
+ * ```
+ */
+export function callerEmail(request: FastifyRequest): string | undefined {
+  return emailFromIdentity(request as unknown as IdentitySource);
+}
diff --git a/api/src/notifications/inApp/liveBridge.ts b/api/src/notifications/inApp/liveBridge.ts
new file mode 100644
index 000000000..88d9dc11c
--- /dev/null
+++ b/api/src/notifications/inApp/liveBridge.ts
@@ -0,0 +1,70 @@
+import type { PoolClient } from 'pg';
+import { connectionString, hasDatabase } from '../../db/index.js';
+import { drizzleDb } from '../../db/drizzleClient.js';
+import { notificationsRepository } from '../../db/drizzle/client.js';
+import { getSSEManager } from '../../services/sseManager.js';
+
+/** Postgres channel raised by `trigger_notifications_change` on the notifications table. */
+export const CHANNEL = 'notifications_changed';
+/** SSE event name delivered to bell subscribers. */
+export const SSE_EVENT = 'notification';
+/** Subscriber `resourceId` prefix so bell streams never collide with chat manager ids. */
+export const RESOURCE_PREFIX = 'bell:';
+
+type ChangePayload = { table?: string; operation?: string; id?: number };
+
+let client: PoolClient | null = null;
+
+/** Pushes one persisted notification row to every stream owned by its recipient. */
+async function fanOut(id: number): Promise<void> {
+  if (!drizzleDb) return;
+  const row = await notificationsRepository.find(drizzleDb, id);
+  if (!row) return;
+  getSSEManager().broadcast({
+    event: SSE_EVENT,
+    data: row,
+    targetType: 'manager',
+    resourceId: `${RESOURCE_PREFIX}${row.user_email.toLowerCase()}`,
+  });
+}
+
+function onNotification(msg: { channel: string; payload?: string }): void {
+  if (msg.channel !== CHANNEL) return;
+  let payload: ChangePayload;
+  try {
+    payload = JSON.parse(msg.payload ?? '{}') as ChangePayload;
+  } catch (error) {
+    console.error('[notifications-live] Malformed pg_notify payload', error);
+    return;
+  }
+  if (payload.operation !== 'INSERT' || typeof payload.id !== 'number') return;
+  fanOut(payload.id).catch((error) => {
+    console.error('[notifications-live] Fan-out failed', { id: payload.id, error });
+  });
+}
+
+/**
+ * Opens a dedicated connection that listens for notification inserts and
+ * relays them to connected bell streams. Safe to call once at startup.
+ *
+ * @returns Whether the listener is active.
+ *
+ * @example
+ * ```ts
+ * if (await startNotificationLiveBridge()) app.log.info('bell live push on');
+ * ```
+ */
+export async function startNotificationLiveBridge(): Promise<boolean> {
+  if (client) return true;
+  if (!hasDatabase || !drizzleDb) return false;
+  const { createPool } = await import('../../db/createPool.js');
+  const pool = createPool({ connectionString, max: 1 });
+  client = await pool.connect();
+  client.on('notification', onNotification);
+  client.on('error', (error) => {
+    console.error('[notifications-live] LISTEN connection lost', error);
+    client = null;
+  });
+  await client.query(`LISTEN ${CHANNEL}`);
+  return true;
+}
