+ * // ['riley@spotlessbinco.com', 'finance@spotlessbinco.com']
+ * ```
+ */
+export async function saleObserverEmails(db: RepositoryDatabase): Promise<string[]> {
+  const rows = await db
+    .select({ email: users.email })
+    .from(users)
+    .innerJoin(roles, eq(roles.id, users.role_id))
+    .where(and(eq(users.enabled, true), inArray(roles.name, OBSERVER_ROLE_NAMES)));
