+import { and, count, desc, eq, sql } from 'drizzle-orm';
+import { notifications } from '../../db/drizzle/schema.js';
+import {
+  notificationsRepository, type NewNotificationsRow, type NotificationsRow, type RepositoryDatabase,
+} from '../../db/drizzle/client.js';
+
+const byOwner = (email: string) => eq(notifications.user_email, email);
+const unread = eq(notifications.is_read, false);
+
+/** Counts unread bell notifications owned by one user. */
+export async function unreadCountFor(db: RepositoryDatabase, email: string): Promise<number> {
+  const [row] = await db.select({ value: count() }).from(notifications)
+    .where(and(byOwner(email), unread));
+  return row?.value ?? 0;
+}
+
+/** Lists one user's notifications, newest first, with the matching total. */
+export async function listFor(
+  db: RepositoryDatabase, email: string,
+  page: { limit: number; offset: number; unreadOnly: boolean },
+): Promise<{ rows: NotificationsRow[]; total: number }> {
+  const where = page.unreadOnly ? and(byOwner(email), unread) : byOwner(email);
+  const [rows, [totalRow]] = await Promise.all([
+    db.select().from(notifications).where(where)
+      .orderBy(desc(notifications.created_at)).limit(page.limit).offset(page.offset),
+    db.select({ value: count() }).from(notifications).where(where),
+  ]);
+  return { rows, total: totalRow?.value ?? 0 };
+}
+
+/** Marks one of the user's notifications read; ignores rows owned by others. */
+export async function markReadFor(db: RepositoryDatabase, email: string, id: number): Promise<boolean> {
+  const rows = await db.update(notifications)
+    .set({ is_read: true, read_at: sql`now()` })
+    .where(and(byOwner(email), eq(notifications.id, id))).returning({ id: notifications.id });
+  return rows.length > 0;
+}
+
+/** Marks every unread notification of the user read and reports how many changed. */
+export async function markAllReadFor(db: RepositoryDatabase, email: string): Promise<number> {
+  const rows = await db.update(notifications)
+    .set({ is_read: true, read_at: sql`now()` })
+    .where(and(byOwner(email), unread)).returning({ id: notifications.id });
+  return rows.length;
+}
+
+/** Deletes one of the user's notifications; ignores rows owned by others. */
+export async function deleteFor(db: RepositoryDatabase, email: string, id: number): Promise<boolean> {
+  const rows = await db.delete(notifications)
+    .where(and(byOwner(email), eq(notifications.id, id))).returning({ id: notifications.id });
+  return rows.length > 0;
+}
+
+/**
+ * Inserts a notification unless one with the same dedupe key already exists
+ * for the recipient. The key lives in `metadata.dedupe_key`.
+ *
+ * @example
+ * ```ts
+ * await createOnce(db, 'sale:pi_123', { user_email, type: 'success', title, message, metadata });
+ * ```
+ */
+export async function createOnce(
+  db: RepositoryDatabase, dedupeKey: string, row: NewNotificationsRow,
+): Promise<NotificationsRow | null> {
+  const existing = await db.select({ id: notifications.id }).from(notifications)
+    .where(and(byOwner(row.user_email), sql`${notifications.metadata}->>'dedupe_key' = ${dedupeKey}`))
+    .limit(1);
+  if (existing.length > 0) return null;
+  return notificationsRepository.create(db, {
+    ...row, metadata: { ...(row.metadata ?? {}), dedupe_key: dedupeKey },
+  });
+}
