+import type { FastifyInstance } from 'fastify';
+import { callerEmail } from './identity.js';
+import { RESOURCE_PREFIX } from './liveBridge.js';
+import { getSSEManager } from '../../services/sseManager.js';
+import { isOriginAllowed, normalizeOrigin } from '../../util/cors.js';
+
+/**
+ * Registers `GET /v1/notifications/stream`, a per-user Server-Sent Events feed
+ * that receives every notification row inserted for the caller.
+ *
+ * Must be registered inside the Keycloak-protected scope so `request.auth`
+ * or the Rust session is already hydrated.
+ *
+ * @param app - Protected Fastify scope.
+ *
+ * @example
+ * ```ts
+ * await registerNotificationStreamRoute(protectedApp);
+ * ```
+ */
+export async function registerNotificationStreamRoute(app: FastifyInstance): Promise<void> {
+  app.get('/v1/notifications/stream', async (request, reply) => {
+    const email = callerEmail(request);
+    if (!email) return reply.status(401).send({ message: 'unauthorized' });
+
+    reply.header('Content-Type', 'text/event-stream')
+      .header('Cache-Control', 'no-cache')
+      .header('Connection', 'keep-alive')
+      .header('X-Accel-Buffering', 'no');
+    reply.hijack();
+    const origin = request.headers.origin;
+    if (typeof origin === 'string' && isOriginAllowed(origin)) {
+      reply.raw.setHeader('Access-Control-Allow-Origin', normalizeOrigin(origin));
+      reply.raw.setHeader('Vary', 'Origin');
+      reply.raw.setHeader('Access-Control-Allow-Credentials', 'true');
+    }
+
+    const sse = getSSEManager();
+    const subscriberId = sse.addSubscriber({
+      type: 'manager',
+      resourceId: `${RESOURCE_PREFIX}${email}`,
+      reply,
+      metadata: { user_email: email, user_agent: request.headers['user-agent'], ip: request.ip },
+    });
+    app.log.info({ subscriberId, user_email: email }, '[notifications-live] stream opened');
+    request.raw.on('close', () => sse.removeSubscriber(subscriberId));
+  });
+}
