+import React from 'react';
+import { BellIcon } from '@heroicons/react/24/outline';
+import { formatTimeAgo, notificationIcon, type Notification } from './notificationFormat';
+
+interface Props {
+  panelId: string;
+  position: { top: number; left: number };
+  loading: boolean;
+  notifications: Notification[];
+  unreadCount: number;
+  onMarkAllRead: () => void;
+  onOpen: (notification: Notification) => void;
+  onDelete: (id: number) => void;
+}
+
+/** Dropdown body rendered by the bell; portal placement is the caller's job. */
+export const NotificationPanel = React.forwardRef<HTMLDivElement, Props>(function NotificationPanel(
+  { panelId, position, loading, notifications, unreadCount, onMarkAllRead, onOpen, onDelete }, ref,
+) {
+  const row = (n: Notification) => (
+    <div key={n.id} onClick={() => onOpen(n)} data-grid-row="notification"
+      className={`border-b border-gray-200 dark:border-gray-700 p-4 hover:bg-gray-50 dark:hover:bg-gray-800 cursor-pointer transition-colors ${!n.is_read ? 'bg-blue-50 dark:bg-blue-900/10' : ''}`}>
+      <div className="flex items-start gap-3">
+        <span className="text-2xl flex-shrink-0">{notificationIcon(n.type)}</span>
+        <div className="flex-1 min-w-0">
+          <div className="flex items-start justify-between gap-2">
+            <p className="font-medium text-gray-900 dark:text-white text-sm">{n.title}</p>
+            <button onClick={(e) => { e.stopPropagation(); onDelete(n.id); }} className="text-gray-400 hover:text-red-500 flex-shrink-0" aria-label="Delete">×</button>
+          </div>
+          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{n.message}</p>
+          <div className="flex items-center gap-2 mt-2">
+            <span className="text-xs text-gray-500 dark:text-gray-500">{formatTimeAgo(n.created_at)}</span>
+            {!n.is_read && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300">New</span>}
+          </div>
+        </div>
+      </div>
+    </div>
+  );
+  return (
+    <div id={panelId} ref={ref} style={position}
+      className="fixed w-96 max-h-[600px] bg-white dark:bg-gray-900 rounded-lg shadow-2xl border border-gray-200 dark:border-gray-700 overflow-hidden z-[9999]">
+      <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
+        <h3 className="font-semibold text-gray-900 dark:text-white">Notifications</h3>
+        {unreadCount > 0 && <button onClick={onMarkAllRead} className="text-sm text-blue-600 dark:text-blue-400 hover:underline">Mark all read</button>}
+      </div>
+      <div className="overflow-y-auto max-h-[500px]">
+        {loading ? (
+          <div className="p-8 text-center text-gray-500 dark:text-gray-400">Loading notifications...</div>
+        ) : notifications.length === 0 ? (
+          <div className="p-8 text-center text-gray-500 dark:text-gray-400">
+            <BellIcon className="h-12 w-12 mx-auto mb-3 opacity-50" />
+            <p className="font-medium text-gray-900 dark:text-white mb-2">All caught up!</p>
+            <p className="text-sm">You have no notifications at this time.</p>
+            <p className="text-xs text-gray-400 dark:text-gray-500 mt-3">New notifications will appear here as they arrive.</p>
+          </div>
+        ) : notifications.map(row)}
+      </div>
+      {notifications.length > 0 && (
+        <div className="px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-center">
+          <a href="/admin/notifications" className="text-sm text-blue-600 dark:text-blue-400 hover:underline">View all notifications</a>
+        </div>
+      )}
+    </div>
+  );
+});
