+import React from 'react';
+import { createPortal } from 'react-dom';
+import type { LiveNotification } from '../../lib/notificationStream';
+
+const TONE: Record<string, string> = {
+  success: 'border-green-300 dark:border-green-700',
+  error: 'border-red-300 dark:border-red-700',
+  warning: 'border-yellow-300 dark:border-yellow-700',
+  info: 'border-blue-300 dark:border-blue-700',
+};
+
+interface Props {
+  notification: LiveNotification | null;
+  onDismiss: () => void;
+  onOpen: (notification: LiveNotification) => void;
+}
+
+/**
+ * Bottom-right toast for a notification that just arrived on the live stream.
+ *
+ * @example
+ * ```tsx
+ * <NotificationToast notification={toast} onDismiss={dismiss} onOpen={open} />
+ * ```
+ */
+export const NotificationToast: React.FC<Props> = ({ notification, onDismiss, onOpen }) => {
+  if (!notification) return null;
+  const tone = TONE[notification.type] ?? 'border-gray-300 dark:border-gray-700';
+  const shell = `fixed bottom-4 right-4 z-[9999] w-80 rounded-lg border bg-white p-4 shadow-2xl dark:bg-gray-900 ${tone}`;
+  return createPortal(
+    <div role="status" aria-live="polite" data-testid="notification-toast" className={shell}>
+      <div className="flex items-start justify-between gap-3">
+        <button type="button" onClick={() => onOpen(notification)} className="min-w-0 flex-1 text-left">
+          <p className="truncate text-sm font-semibold text-gray-900 dark:text-white">{notification.title}</p>
+          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">{notification.message}</p>
+        </button>
+        <button type="button" onClick={onDismiss} aria-label="Dismiss notification" className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
+          ×
+        </button>
+      </div>
+    </div>,
+    document.body,
+  );
+};
