+/** Bell row shape as returned by `notificationsList`. */
+export interface Notification {
+  id: number;
+  user_email: string;
+  type: 'success' | 'error' | 'warning' | 'info';
+  title: string;
+  message: string;
+  metadata?: Record<string, any>;
+  is_read: boolean;
+  created_at: string;
+  read_at?: string | null;
+}
+
+/** Emoji glyph for a notification tone. */
+export function notificationIcon(type: string): string {
+  switch (type) {
+    case 'success': return '✅';
+    case 'error': return '❌';
+    case 'warning': return '⚠️';
+    case 'info': return 'ℹ️';
+    default: return '📢';
+  }
+}
+
+/** Human relative timestamp such as `3m ago`. */
+export function formatTimeAgo(dateString: string): string {
+  const seconds = Math.floor((Date.now() - new Date(dateString).getTime()) / 1000);
+  if (seconds < 60) return 'just now';
+  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
+  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
+  return `${Math.floor(seconds / 86400)}d ago`;
+}
+
+/**
+ * Computes the fixed position for the bell dropdown so it never overflows
+ * the viewport horizontally.
+ *
+ * @example
+ * ```ts
+ * const pos = dropdownPositionFor(buttonRef.current!.getBoundingClientRect());
+ * ```
+ */
+export function dropdownPositionFor(rect: DOMRect, width = 384): { top: number; left: number } {
+  let left = rect.right - width;
+  if (left < 8) left = rect.left;
+  if (left + width > window.innerWidth - 8) left = window.innerWidth - width - 8;
+  return { top: rect.bottom + 8, left: Math.max(8, left) };
+}
