+import { useCallback, useEffect, useState, type RefObject } from 'react';
+import { useLiveNotifications } from './useLiveNotifications';
+import type { useNotificationInbox } from './useNotificationInbox';
+
+type Inbox = ReturnType<typeof useNotificationInbox>;
+
+/**
+ * Bell behaviour that is not rendering: live-stream arrivals, the legacy
+ * `targeting-job-success` window event, and click-outside dismissal.
+ *
+ * @returns Highlight state plus the current toast and its dismiss handler.
+ *
+ * @example
+ * ```ts
+ * const { highlight, setHighlight, toast, dismiss } = useBellBehaviour(inbox, isOpen, setIsOpen, refs, live);
+ * ```
+ */
+export function useBellBehaviour(
+  inbox: Inbox,
+  isOpen: boolean,
+  setIsOpen: (open: boolean) => void,
+  refs: { dropdown: RefObject<HTMLDivElement | null>; button: RefObject<HTMLButtonElement | null> },
+  liveEnabled: boolean,
+) {
+  const [highlight, setHighlight] = useState(false);
+
+  const onArrive = useCallback(() => {
+    setHighlight(true);
+    void inbox.refreshUnread();
+    if (isOpen) void inbox.load();
+  }, [inbox, isOpen]);
+
+  const { toast, dismiss } = useLiveNotifications(liveEnabled, onArrive);
+
+  useEffect(() => {
+    if (liveEnabled && isOpen) void inbox.refreshUnread();
+  }, [inbox, liveEnabled, isOpen]);
+
+  useEffect(() => {
+    if (!isOpen) return;
+    const onClickOutside = (event: MouseEvent) => {
+      const target = event.target as Node;
+      if (!refs.dropdown.current?.contains(target) && !refs.button.current?.contains(target)) setIsOpen(false);
+    };
+    document.addEventListener('mousedown', onClickOutside);
+    return () => document.removeEventListener('mousedown', onClickOutside);
+  }, [isOpen, refs, setIsOpen]);
+
+  useEffect(() => {
+    window.addEventListener('targeting-job-success', onArrive);
+    return () => window.removeEventListener('targeting-job-success', onArrive);
+  }, [onArrive]);
+
+  return { highlight, setHighlight, toast, dismiss };
+}
