+import { useEffect, useState } from 'react';
+import { subscribeToNotifications, type LiveNotification } from '../../lib/notificationStream';
+
+const TOAST_MS = 8_000;
+
+/**
+ * Keeps the bell live: subscribes to the caller's notification stream while
+ * authenticated, surfaces each pushed row as a short-lived toast, and lets the
+ * bell re-sync its unread count.
+ *
+ * @param enabled - Subscribe only when the user is authenticated.
+ * @param onArrive - Invoked for every pushed notification (e.g. refetch count).
+ * @returns The toast currently showing and a dismiss handler.
+ *
+ * @example
+ * ```tsx
+ * const { toast, dismiss } = useLiveNotifications(isAuthenticated, fetchUnreadCount);
+ * ```
+ */
+export function useLiveNotifications(enabled: boolean, onArrive: (row: LiveNotification) => void) {
+  const [toast, setToast] = useState<LiveNotification | null>(null);
+
+  useEffect(() => {
+    if (!enabled) return;
+    return subscribeToNotifications((row) => {
+      setToast(row);
+      onArrive(row);
+    });
+  }, [enabled, onArrive]);
+
+  useEffect(() => {
+    if (!toast) return;
+    const timer = setTimeout(() => setToast(null), TOAST_MS);
+    return () => clearTimeout(timer);
+  }, [toast]);
+
+  return { toast, dismiss: () => setToast(null) };
+}
