+import { useCallback, useState } from 'react';
+import {
+  notificationsDelete, notificationsGetUnreadCount, notificationsList,
+  notificationsMarkAllAsRead, notificationsMarkAsRead,
+} from '../../src/client-typescript-api/sdk.gen';
+import type { Notification } from './notificationFormat';
+
+/**
+ * Owns the bell's server state: unread count, the loaded page of rows, and the
+ * read/delete mutations against the oRPC notifications procedures.
+ *
+ * @example
+ * ```ts
+ * const bell = useNotificationInbox();
+ * await bell.refreshUnread();
+ * ```
+ */
+export function useNotificationInbox() {
+  const [unreadCount, setUnreadCount] = useState(0);
+  const [notifications, setNotifications] = useState<Notification[]>([]);
+  const [loading, setLoading] = useState(false);
+  const [lastErrorTime, setLastErrorTime] = useState<number | null>(null);
+
+  const refreshUnread = useCallback(async () => {
+    try {
+      const { data } = await notificationsGetUnreadCount();
+      if (data) setUnreadCount(data.count);
+    } catch (error) {
+      const now = Date.now();
+      if (!lastErrorTime || now - lastErrorTime > 60_000) {
+        console.warn('Notification bell: API unavailable', error instanceof Error ? error.message : String(error));
+        setLastErrorTime(now);
+      }
+    }
+  }, [lastErrorTime]);
+
+  const load = useCallback(async () => {
+    setLoading(true);
+    try {
+      const { data } = await notificationsList({ body: { limit: 20, offset: 0, unreadOnly: false } });
+      if (data) {
+        setNotifications(data.notifications as Notification[]);
+        setUnreadCount(data.notifications.filter((n) => !n.is_read).length);
+      }
+    } catch (error) {
+      console.error('Failed to fetch notifications:', error);
+    } finally {
+      setLoading(false);
+    }
+  }, []);
+
+  const markRead = useCallback(async (id: number) => {
+    await notificationsMarkAsRead({ body: { notificationId: id } }).catch((e) => console.error(e));
+    setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
+    setUnreadCount((prev) => Math.max(0, prev - 1));
+  }, []);
+
+  const markAllRead = useCallback(async () => {
+    await notificationsMarkAllAsRead({ body: {} }).catch((e) => console.error(e));
+    setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
+    setUnreadCount(0);
+  }, []);
+
+  const remove = useCallback(async (id: number) => {
+    await notificationsDelete({ body: { notificationId: id } }).catch((e) => console.error(e));
+    setNotifications((prev) => {
+      const target = prev.find((n) => n.id === id);
+      if (target && !target.is_read) setUnreadCount((count) => Math.max(0, count - 1));
+      return prev.filter((n) => n.id !== id);
+    });
+  }, []);
+
+  return { unreadCount, notifications, loading, refreshUnread, load, markRead, markAllRead, remove };
+}
