+/** Notification row as pushed by `/v1/notifications/stream`. */
+export interface LiveNotification {
+  id: number;
+  user_email: string;
+  type: 'success' | 'error' | 'warning' | 'info' | string;
+  title: string;
+  message: string;
+  metadata?: Record<string, unknown>;
+  is_read: boolean;
+  created_at: string;
+}
+
+/**
+ * Parses one `text/event-stream` frame (already split on the blank line)
+ * into a notification, or `null` for pings, connection events, or bad JSON.
+ *
+ * @example
+ * ```ts
+ * parseNotificationFrame('event: notification\ndata: {"id":1,...}');
+ * ```
+ */
+export function parseNotificationFrame(frame: string): LiveNotification | null {
+  let eventName = 'message';
+  const data: string[] = [];
+  for (const line of frame.split('\n')) {
+    if (line.startsWith('event:')) eventName = line.slice(6).trim();
+    else if (line.startsWith('data:')) data.push(line.slice(5).trim());
+  }
+  if (eventName !== 'notification' || data.length === 0) return null;
+  try {
+    const parsed = JSON.parse(data.join('\n')) as { data?: LiveNotification } | LiveNotification;
+    const row = 'data' in parsed && parsed.data ? parsed.data : (parsed as LiveNotification);
+    return { ...row, metadata: row.metadata ?? {} };
+  } catch {
+    return null;
+  }
+}
