+import { authFetchOptions } from './keycloak';
+import { getApiBaseUrl } from './api-config';
+import { parseNotificationFrame, type LiveNotification } from './notificationFrame';
+
+export type { LiveNotification } from './notificationFrame';
+
+const RETRY_MS = [1_000, 2_000, 5_000, 10_000, 30_000];
+
+async function pump(body: ReadableStream<Uint8Array>, onFrame: (frame: string) => void): Promise<void> {
+  const reader = body.pipeThrough(new TextDecoderStream()).getReader();
+  let buffer = '';
+  for (;;) {
+    const { value, done } = await reader.read();
+    if (done) return;
+    buffer += value;
+    const frames = buffer.split('\n\n');
+    buffer = frames.pop() ?? '';
+    frames.forEach(onFrame);
+  }
+}
+
+/**
+ * Subscribes to the caller's bell stream with the Keycloak bearer token.
+ *
+ * `EventSource` cannot carry an `Authorization` header, so this reads the
+ * SSE body through `fetch` and reconnects with capped backoff.
+ *
+ * @param onNotification - Called for every notification pushed to this user.
+ * @returns Disposer that closes the stream and stops reconnecting.
+ *
+ * @example
+ * ```ts
+ * const stop = subscribeToNotifications((n) => console.log(n.title));
+ * stop();
+ * ```
+ */
+export function subscribeToNotifications(onNotification: (row: LiveNotification) => void): () => void {
+  const controller = new AbortController();
+  let attempt = 0;
+
+  const run = async (): Promise<void> => {
+    while (!controller.signal.aborted) {
+      try {
+        const response = await fetch(`${getApiBaseUrl()}/v1/notifications/stream`,
+          authFetchOptions({ signal: controller.signal, headers: { Accept: 'text/event-stream' } }));
+        if (!response.ok || !response.body) throw new Error(`stream ${response.status}`);
+        attempt = 0;
+        await pump(response.body, (frame) => {
+          const row = parseNotificationFrame(frame);
+          if (row) onNotification(row);
+        });
+      } catch (error) {
+        if (controller.signal.aborted) return;
+        console.debug('[notifications] stream dropped, retrying', error);
+      }
+      await new Promise((resolve) => setTimeout(resolve, RETRY_MS[Math.min(attempt++, RETRY_MS.length - 1)]));
+    }
+  };
+  void run();
+  return () => controller.abort();
+}

