+ * @example
+ * ```ts
+ * const values = toStepPatch({ offerId: 100 });
+ * console.log(values.offer_id); // 100
+ * ```
+ */
+export function toStepPatch(
+  patch: UpdateDraftStepInput['patch'],
+): Partial<NewFunnelStepsRow> {
+  const values: Partial<NewFunnelStepsRow> = {};
+  if (patch.name !== undefined) values.name = patch.name;
+  if (patch.stepType !== undefined) {
+    values.step_type = patch.stepType as NewFunnelStepsRow['step_type'];
+  }
+  if (patch.slug !== undefined) values.slug = patch.slug;
+  if (patch.primaryCtaText !== undefined) {
+    values.primary_cta_text = patch.primaryCtaText;
+  }
+  if (patch.offerId !== undefined) values.offer_id = patch.offerId;
+  if (patch.pageId !== undefined) values.page_id = patch.pageId;
+  if (patch.templateHint !== undefined) {
+    values.template_hint = patch.templateHint;
+  }
+  if (Object.keys(values).length === 0) {
+    throw new ORPCError('BAD_REQUEST', {
+      message: 'At least one step field must be changed',
+    });
+  }
+  values.updated_at = new Date().toISOString();
+  return values;
+}
