+import {
+  offersRepository,
+  type NewOffersRow,
+  type OffersRow,
+} from '../db/drizzle/client.js';
+import { drizzleDb } from '../db/drizzleClient.js';
+
+export type OfferUpdateValue = string | number | boolean | Record<string, unknown> | null;
+export type OfferUpdates = Record<string, OfferUpdateValue | undefined>;
+
+function database() {
+  if (!drizzleDb) throw new Error('Database connection not available');
+  return drizzleDb;
+}
+
+export async function findCurrentOffer(offerId: number): Promise<OffersRow> {
+  const offer = await offersRepository.find(database(), offerId);
+  if (!offer) throw new Error(`Offer with ID ${offerId} not found`);
+  return offer;
+}
+
+export function hasDeletedPayload(offer: OffersRow): boolean {
+  const payload = offer.payload;
+  return payload !== null && typeof payload === 'object'
+    && !Array.isArray(payload) && payload.deleted_at !== undefined
+    && payload.deleted_at !== null;
+}
+
+export async function updateOfferRow(
+  offerId: number,
+  updates: OfferUpdates,
+): Promise<OffersRow> {
+  const values = Object.fromEntries(
+    Object.entries(updates).filter((entry) => entry[1] !== undefined),
+  ) as Partial<NewOffersRow>;
+  const saved = await offersRepository.update(database(), offerId, {
+    ...values,
+    updated_at: new Date().toISOString(),
+  });
+  if (!saved) throw new Error(`Offer with ID ${offerId} not found`);
+  return saved;
+}
