+import { os } from '@orpc/server';
+import { z } from 'zod';
+import { updateStripeProduct } from '../stripe/offers.js';
+import { offerActor, requireOfferAdmin } from './auth.js';
+import { OfferDeleteInputSchema } from './offerProcedureSchemas.js';
+import {
+  findCurrentOffer,
+  hasDeletedPayload,
+  updateOfferRow,
+} from './offerCurrentRepository.js';
+
+/** Soft-deletes an offer through RustyRoad repositories and deactivates Stripe. */
+export const deleteOffer = os
+  .route({ method: 'POST', path: '/orpc/offers/delete' })
+  .input(OfferDeleteInputSchema)
+  .output(z.object({ success: z.boolean(), offerId: z.number() }))
+  .handler(async ({ input, context }) => {
+    requireOfferAdmin(context);
+    const current = await findCurrentOffer(input.offerId);
+    if (hasDeletedPayload(current)) {
+      throw new Error(`Offer with ID ${input.offerId} not found`);
+    }
+
+    if (current.stripe_product_id) {
+      try {
+        await updateStripeProduct(current.stripe_product_id, { active: false });
+      } catch (error) {
+        console.error('[Offers] Failed to deactivate Stripe product:', error);
+      }
+    }
+
+    await updateOfferRow(input.offerId, {
+      payload: {
+        ...(current.payload ?? {}),
+        deleted_at: new Date().toISOString(),
+        deleted_by: offerActor(context),
+      },
+    });
+
+    return { success: true, offerId: input.offerId };
+  });
