+import { pool } from '../db/pool.js';
+import { fallbackPriceSnapshot } from './fallbackPriceSnapshot.js';
+import { persistStripeOfferLinks } from './persistStripeOfferLinks.js';
+import {
+  getPricingFromOnboardingConfig,
+  resolveOfferPriceSnapshot,
+} from './offerPricing.js';
+import { updateOfferRow, type OfferUpdates } from './offerCurrentRepository.js';
+
+function requirePool() {
+  if (!pool) throw new Error('Database connection not available');
+  return pool;
+}
+
+export async function persistOfferUpdates(offerId: number, updates: OfferUpdates) {
+  if (!Object.values(updates).some((value) => value !== undefined)) {
+    throw new Error('No fields to update');
+  }
+
+  const updatedOffer = await updateOfferRow(offerId, updates);
+  const pricing = getPricingFromOnboardingConfig(updatedOffer.onboarding_config);
+  const fallbackPrice = fallbackPriceSnapshot({
+    priceId: updatedOffer.stripe_price_id,
+    productId: updatedOffer.stripe_product_id,
+    unitAmountCents: pricing?.unit_amount_cents ?? null,
+    currency: pricing?.currency ?? null,
+    interval: pricing?.interval ?? null,
+    intervalCount: pricing?.interval_count ?? null,
+    metadata: { offer_type: updatedOffer.offer_type ?? 'standard' },
+  });
+  const priceSnapshot = await resolveOfferPriceSnapshot(
+    updatedOffer.stripe_product_id,
+    fallbackPrice,
+  );
+  return persistStripeOfferLinks(requirePool(), {
+    offerId: Number(updatedOffer.id),
+    stripeProductId: updatedOffer.stripe_product_id,
+    name: updatedOffer.name,
+    description: updatedOffer.description,
+    price: priceSnapshot,
+    metadata: {
+      source: 'offer_update',
+      offer_type: updatedOffer.offer_type ?? 'standard',
+      stripe_price_id: updatedOffer.stripe_price_id,
+    },
+  });
+}
