+import { os } from '@orpc/server';
+import { serializeRow } from '../types/helpers.js';
+import { OfferOutputSchema, type OfferOutput as Offer } from './offerSchemas.js';
+import { requireOfferAdmin } from './auth.js';
+import { findCurrentOffer } from './offerCurrentRepository.js';
+import { OfferUpdateInputSchema } from './offerProcedureSchemas.js';
+import { persistOfferUpdates } from './offerUpdatePersist.js';
+import { syncOfferUpdatesToStripe } from './offerUpdateStripeSync.js';
+
+/** Updates an offer through RustyRoad repositories and mirrors product fields to Stripe. */
+export const updateOffer = os
+  .route({ method: 'POST', path: '/orpc/offers/update' })
+  .input(OfferUpdateInputSchema)
+  .output(OfferOutputSchema)
+  .handler(async ({ input, context }) => {
+    requireOfferAdmin(context);
+    try {
+      const { offerId, syncToStripe = true, ...updates } = input;
+      const currentOffer = await findCurrentOffer(offerId);
+      if (syncToStripe) {
+        try {
+          await syncOfferUpdatesToStripe(currentOffer, updates);
+        } catch (stripeError) {
+          console.error('[Offers] Failed to sync to Stripe:', stripeError);
+        }
+      }
+
+      const linkedOffer = await persistOfferUpdates(offerId, updates);
+      return serializeRow(linkedOffer) as unknown as Offer;
+    } catch (error) {
+      console.error('[Offers] Error updating offer:', error);
+      throw new Error(error instanceof Error ? error.message : 'Failed to update offer');
+    }
+  });
