+import { updateStripeProduct } from '../stripe/offers.js';
+import type { OffersRow } from '../db/drizzle/client.js';
+import { asRecord, metadataValue } from './offerPricing.js';
+import type { OfferUpdates } from './offerCurrentRepository.js';
+
+type StripeProductUpdates = {
+  name?: string;
+  description?: string;
+  active?: boolean;
+  metadata?: Record<string, string>;
+};
+
+function rolloverMetadata(updates: OfferUpdates): Record<string, string> | undefined {
+  const config = asRecord(updates.onboarding_config);
+  const rolloverData = asRecord(config?.rollover);
+  const creditsPerCycle = metadataValue(rolloverData?.credits_per_cycle) ?? '0';
+  const metadata = { offer_type: 'rollover_credits', credits_per_cycle: creditsPerCycle };
+  const rolloverCap = metadataValue(rolloverData?.cap);
+  return rolloverCap === undefined ? metadata : { ...metadata, rollover_cap: rolloverCap };
+}
+
+export async function syncOfferUpdatesToStripe(
+  currentOffer: OffersRow,
+  updates: OfferUpdates,
+): Promise<void> {
+  const stripeProductId = currentOffer.stripe_product_id;
+  if (!stripeProductId) return;
+  const stripeUpdates: StripeProductUpdates = {};
+  if (typeof updates.name === 'string') stripeUpdates.name = updates.name;
+  if (updates.description !== undefined) {
+    stripeUpdates.description = typeof updates.description === 'string'
+      ? updates.description : undefined;
+  }
+  const finalOfferType = updates.offer_type || currentOffer.offer_type;
+  if (finalOfferType === 'rollover-upsell' && updates.onboarding_config) {
+    stripeUpdates.metadata = rolloverMetadata(updates);
+  }
+  if (Object.keys(stripeUpdates).length === 0) return;
+  await updateStripeProduct(stripeProductId, stripeUpdates);
+  console.log('[Offers] Synced updates to Stripe product:', stripeProductId);
+}
