+/**
+ * Records an upsell decline and follows the published funnel transition.
+ *
+ * @param {HTMLAnchorElement|HTMLButtonElement} control - Decline control selected by the customer.
+ * @returns {Promise<void>} Resolves after navigation or after displaying an error.
+ * @example
+ * ```js
+ * const link = document.querySelector('[data-component="decline_link"] a');
+ * await declineUpsell(link);
+ * ```
+ */
+async function declineUpsell(control) {
+  if (control.dataset.declinePending === 'true') return;
+  const [, routeType, funnelSlug, stepSlug] = window.location.pathname.split('/');
+  if (routeType !== 'f' || !funnelSlug || !stepSlug) return;
+  control.dataset.declinePending = 'true';
+  control.setAttribute('aria-disabled', 'true');
+  try {
+    const response = await fetch(
+      `/f/${encodeURIComponent(funnelSlug)}/${encodeURIComponent(stepSlug)}/act`,
+      {
+        method: 'POST',
+        credentials: 'include',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ decision: 'decline_upsell', value_cents: 0 }),
+      },
+    );
+    let result = {};
+    try { result = await response.json(); } catch {}
+    if (!response.ok || !result.success) {
+      throw new Error(result.error || 'The decline could not be recorded.');
+    }
+    window.location.assign(result.next_step_url || '/thank-you');
+  } catch (error) {
+    const eventData = { purchase_type: 'upsell', failure_stage: 'transition' };
