+/**
+ * Processes a signed upsell offer using the payment method saved by checkout.
+ * A successful payment is remembered so retries do not submit it twice.
+ * @param {HTMLButtonElement} button - The rendered upsell acceptance button.
+ * @returns {Promise<void>} Resolves after navigation or after displaying an error.
+ * @example
+ * ```js
+ * const button = document.querySelector('[data-offer-action="accept"]');
+ * await acceptUpsell(button);
+ * ```
+ */
+async function acceptUpsell(button) {
+  if (button.disabled) return;
+  const card = button.closest('.one-click-upsell-container, .upsell-card-container') || button.closest('[data-offer-token]');
+  const token = card?.dataset.offerToken || button.dataset.offerToken;
+  const [, routeType, funnelSlug, stepSlug] = window.location.pathname.split('/');
+  if (!card || !token || routeType !== 'f' || !funnelSlug || !stepSlug) return;
+  const originalText = button.textContent;
+  button.disabled = true;
+  button.textContent = 'Processing securely…';
+  let paymentSucceeded = button.dataset.paymentComplete === 'true';
+  try {
+    const price = Number.parseFloat(card.dataset.offerPrice || '0');
+    const quantity = Number.parseInt(card.dataset.paneCount || '1', 10) || 1;
+    const value = price * quantity;
+    if (button.dataset.paymentComplete !== 'true') {
+      const recurringOffer = window.__OFFER__?.is_recurring === true;
+      const subscription = card.dataset.offerPurchase === 'subscription' || recurringOffer;
+      const endpoint = subscription
+        ? '/api/stripe/subscribe-saved-method'
+        : '/api/stripe/charge-saved-method';
+      const payload = subscription
+        ? {
+            offer_token: token,
+            bins: Number.parseInt(card.dataset.selectedBins || '2', 10),
+            frequency: card.dataset.selectedFrequency || 'monthly',
+          }
+        : {
+            offer_token: token,
+            quantity: Number.parseInt(card.dataset.paneCount || '', 10),
+          };
+      const paymentResponse = await fetch(endpoint, {
+        method: 'POST',
+        credentials: 'include',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(payload),
+      });
+      let payment = {};
+      try { payment = await paymentResponse.json(); } catch {}
+      if (!paymentResponse.ok || !payment.success) {
+        throw new Error(payment.error || 'The upsell payment could not be completed.');
+      }
+      button.dataset.paymentComplete = 'true';
+      paymentSucceeded = true;
+    }
+    const actionResponse = await fetch(
+      `/f/${encodeURIComponent(funnelSlug)}/${encodeURIComponent(stepSlug)}/act`,
+      {
+        method: 'POST',
+        credentials: 'include',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          decision: 'accept_upsell',
+          value_cents: Math.round(value * 100),
+          offer_token: token,
+        }),
+      },
+    );
+    let action = {};
+    try { action = await actionResponse.json(); } catch {}
+    if (!actionResponse.ok) throw new Error('Payment succeeded, but the next page did not load. Retry to continue.');
+    window.location.assign(action.next_step_url || '/thank-you?redirect_status=succeeded');
+  } catch (error) {
+    const eventName = paymentSucceeded ? 'custom:funnel_transition_failed' : 'payment_failed';
+    const eventData = {
+      purchase_type: 'upsell',
+      failure_stage: paymentSucceeded ? 'transition' : 'payment',
+    };
+    if (typeof window.spotlessEmitBusinessEvent === 'function') {
+      window.spotlessEmitBusinessEvent(eventName, eventData, button);
+    } else {
+      window.spotlessBusinessEventQueue = window.spotlessBusinessEventQueue || [];
+      window.spotlessBusinessEventQueue.push([eventName, eventData, button]);
+    }
+    let message = card.querySelector('.upsell-runtime-error');
+    if (!message) {
+      message = document.createElement('p');
+      message.className = 'upsell-runtime-error mt-3 text-sm text-red-400';
+      message.setAttribute('role', 'alert');
+      card.appendChild(message);
+    }
+    message.textContent = error instanceof Error ? error.message : 'Unable to process this offer.';
+    button.disabled = false;
+    button.textContent = originalText;
+  }
+}
+/**
+ * Delegates clicks from database-rendered acceptance buttons to `acceptUpsell`.
+ * @param {MouseEvent} event - A document click event.
+ * @returns {void}
+ * @example
+ * ```js
+ * document.addEventListener('click', handleUpsellClick);
+ * ```
+ */
+function handleUpsellClick(event) {
+  const target = event.target instanceof Element ? event.target : null;
+  const button = target?.closest('[data-offer-action="accept"]');
+  if (!(button instanceof HTMLButtonElement)) return;
+  event.preventDefault();
+  void acceptUpsell(button);
+}
+document.addEventListener('click', handleUpsellClick);
+document.documentElement.dataset.upsellHandler = 'ready';
