+import { expect } from '@rstest/playwright';
+import type { Page } from 'playwright';
+
+export type SelectorCharge = { offerId: number; amountCents: number; paymentIntentId: string };
+
+/**
+ * Accepts one preset offer from the rendered `one_click_offer_selector`.
+ *
+ * Asserts the option shows the expected price before selecting it, then clicks
+ * the shared accept button, which charges the saved card through
+ * `/api/stripe/charge-saved-method` and follows the published `accept`
+ * transition through `/act`.
+ *
+ * @param page - Browser page on the funnel step that renders the selector.
+ * @param offerId - Offer the customer picks.
+ * @param expectedAmountCents - Price the option must display.
+ * @returns The chosen offer, its price, and the Stripe PaymentIntent charged.
+ * @throws When the option is missing, priced differently, or the charge fails.
+ *
+ * @example
+ * ```ts
+ * const charge = await acceptSelectorOffer(page, 100, 20000);
+ * console.log(charge.paymentIntentId); // "pi_..."
+ * ```
+ */
+export async function acceptSelectorOffer(
+  page: Page,
+  offerId: number,
+  expectedAmountCents: number,
+): Promise<SelectorCharge> {
+  const selector = page.locator('[data-component="one_click_offer_selector"]');
+  await expect(selector).toBeVisible({ timeout: 30_000 });
+  const option = selector.locator(`[role="radio"][data-offer-id="${offerId}"]`);
+  await expect(option).toHaveAttribute('data-offer-price', String(expectedAmountCents / 100));
+  await expect(option).toHaveAttribute('data-offer-purchase', 'one-time');
+  await expect(option).toContainText(`$${expectedAmountCents / 100}`);
+  await option.click();
+  await expect(option).toHaveAttribute('aria-checked', 'true');
+
+  const charge = page.waitForResponse((response) => response.url()
+    .endsWith('/api/stripe/charge-saved-method')
+      && response.request().method() === 'POST', { timeout: 90_000 });
+  const action = page.waitForResponse((response) => response.url().endsWith('/act')
+    && response.request().method() === 'POST', { timeout: 60_000 });
+  await selector.locator('[data-offer-action="accept"]').click();
+  const chargeResponse = await charge;
+  expect(chargeResponse.status(), 'charge-saved-method status').toBe(200);
+  const body = await chargeResponse.json() as { success?: boolean; payment_intent_id?: string };
+  expect(body.success).toBe(true);
+  expect(body.payment_intent_id).toMatch(/^pi_/);
+  expect((await action).status(), 'funnel accept transition').toBe(200);
+  return { offerId, amountCents: expectedAmountCents, paymentIntentId: body.payment_intent_id! };
+}
